<template>
    <view class="fw-page op-page"><view v-if="error" class="fw-notice error">{{ error }}</view>
        <view v-if="jobId" class="fw-card"><text class="fw-heading-title">登记当前工单异常</text><ops-select v-model="form.category" label="异常类别 *" :items="categories" :disabled="saving" /><view class="fw-field"><text class="fw-label">异常内容及现场处理 *</text><textarea v-model="form.description" class="fw-textarea" maxlength="4000" :disabled="saving" placeholder="说明异常、现场措施和需要协助的事项" /></view><button class="fw-button primary" :disabled="saving || loading" @tap="save">{{ saving ? '提交中…' : '提交异常' }}</button></view>
        <view class="op-toolbar"><button class="fw-button secondary" :disabled="loading || saving" @tap="load">刷新异常列表</button></view><view v-for="row in list" :key="row._id" class="fw-card"><view class="fw-heading"><text class="fw-heading-title">{{ row.batchNo || row.jobId }}</text><text class="fw-badge" :class="{ warning: row.status === 'open' }">{{ row.status === 'resolved' ? '已处理' : '待处理' }}</text></view><text class="op-meta">{{ categoryName(row.category) }} · {{ row.actorName || row.createdByName || '' }}</text><text class="op-pre">{{ row.description }}</text><text v-if="row.resolution" class="op-meta">处理：{{ row.resolution }}</text><button class="fw-button secondary" @tap="openJob(row.jobId)">查看工单</button></view><view v-if="!list.length && !loading" class="fw-card fw-empty"><text class="fw-empty-title">暂无异常记录</text></view><view class="op-toolbar"><button class="fw-button secondary" :disabled="loading || page <= 1" @tap="turn(-1)">上一页</button><text class="fw-note">共 {{ total }} 条</text><button class="fw-button secondary" :disabled="loading || page * 20 >= total" @tap="turn(1)">下一页</button></view>
    </view>
</template>
<script>
import OpsSelect from '@/components/operations/OpsSelect.vue'
import { callOperations, operationsPage, loadOperations, operationRequest } from '@/utils/operations-api.js'
export default { components: { OpsSelect }, mixins: [operationsPage], data() { return { jobId: '', form: { category: '', description: '' }, list: [], total: 0, page: 1, categories: [{ _id: 'quality', name: '质量' }, { _id: 'equipment', name: '设备' }, { _id: 'material', name: '物料' }, { _id: 'safety', name: '安全' }, { _id: 'other', name: '其他' }] } }, onLoad(options) { this.jobId = options.jobId || '' }, onShow() { this.load() }, methods: {
    load() { return loadOperations(this, () => callOperations('listExceptions', { page: this.page, pageSize: 20 }), result => { this.list = result.list; this.total = result.total }) }, clearLoaded() { this.list = []; this.total = 0 },
    categoryName(value) { const row = this.categories.find(item => item._id === value); return row ? row.name : value }, turn(delta) { this.page += delta; this.load() }, openJob(id) { uni.navigateTo({ url: '/pages/operations/job-detail?id=' + encodeURIComponent(id) }) },
    async save() { if (this.saving || this.loading) return; if (!this.form.category || !this.form.description.trim()) { this.error = '请选择类别并描述异常'; return }; this.saving = true; this.error = ''; try { const record = { jobId: this.jobId, ...this.form }; await callOperations('saveException', { record, expectedVersion: 0, requestId: operationRequest(this, 'saveException', record) }); this.pendingRequest = null; this.form = { category: '', description: '' }; uni.showToast({ title: '已登记异常', icon: 'success' }); await this.load() } catch (error) { this.error = error.message } finally { this.saving = false } }
} }
</script>
<style lang="scss" scoped>@import '@/styles/operations.scss';</style>
